def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split pre-release (everything after '-')
        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease_part is not None:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert each identifier to tuple (is_numeric, numeric_value or string)
            prerelease_parsed = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_parsed.append((0, int(identifier)))
                else:
                    prerelease_parsed.append((1, identifier))
            prerelease_tuple = tuple(prerelease_parsed)
        else:
            prerelease_tuple = None

        return version_nums, prerelease_tuple

    def sort_key(v):
        version_nums, prerelease_tuple = parse_version(v)

        # For sorting:
        # 1. Compare MAJOR, MINOR, PATCH numerically
        # 2. Version without pre-release sorts after version with pre-release
        #    (so we use False for no pre-release, True for with pre-release in terms of ordering)
        # 3. Pre-release identifiers are compared as parsed tuples

        if prerelease_tuple is None:
            # No pre-release: sorts after same version with pre-release
            return (version_nums, (1,))
        else:
            # Has pre-release: sorts before same version without pre-release
            return (version_nums, (0, prerelease_tuple))

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

